#' Estimate an nlmixr2 model from a simplified model object
#'
#' This is the command used by the `fit_simple` target generated by
#' [tar_nlmixr()]; it is not typically invoked by end users.
#'
#' @details
#' `object` is the simplified `nlmixrui` returned by
#' [nlmixr_object_simplify()] and held as the `object_simple` target in the
#' pipeline. `nlmixr_fit_simple()` passes it to [nlmixr2est::nlmixr()] along
#' with `data`, `est`, `control`, and -- when the caller supplied one --
#' `table`.  An omitted `table` is passed on as omitted rather than as
#' `nlmixr2est::tableControl()`, because nlmixr2est merges the table settings
#' carried on `ui$meta` into the table control only when its own `table`
#' argument is missing.
#'
#' @inheritParams nlmixr2est::nlmixr
#' @param object The simplified `nlmixrui` object returned by
#'   [nlmixr_object_simplify()].
#' @inheritParams tar_nlmixr
#' @inheritParams tar_nlmixr_raw
#' @returns An nlmixr2 fit object, as returned by [nlmixr2est::nlmixr()]. When
#'   `error = "continue"` and the estimation step fails, a failure sentinel of
#'   class `nlmixr2targetsError` (which also inherits from `"try-error"`) is
#'   returned instead; see [tar_nlmixr()].
#' @seealso [tar_nlmixr()], [nlmixr_object_simplify()].
#' @export
nlmixr_fit_simple <- function(object, data, est, control, table,
                              error = c("stop", "continue"), description = NULL) {
  error <- match.arg(error)
  # A failed upstream step (object or data simplification under
  # error = "continue") reaches here as a sentinel in place of the simplified
  # model or data. Pass it straight through: there is nothing to fit.
  if (inherits(object, "nlmixr2targetsError")) return(object)
  if (inherits(data, "nlmixr2targetsError")) return(data)
  # start a configured logger before the fit, so it is logged (see rxEvents.R)
  nlmixr2targets_event_load_logger()
  if (!is.null(description)) {
    # `tar_nlmixr_multimodel()` names its targets after a hash of the model, so
    # the description is the only way to tell from the console which model is
    # being estimated.
    message("Model description: ", description)
  }
  if (identical(error, "continue")) {
    tryCatch(
      nlmixr_fit_simple_run(
        ui = object, data = data, est = est, control = control, table = table
      ),
      error = function(e) nlmixr2targets_error_object(e)
    )
  } else {
    nlmixr_fit_simple_run(
      ui = object, data = data, est = est, control = control, table = table
    )
  }
}

# Run the estimation, forwarding an absent `table` as absent rather than as
# `tableControl()`. The two are not equivalent: nlmixr2est merges the table
# settings carried on `ui$meta` (`addDosing`, `subsetNonmem`, `cores`, `keep`,
# `drop`) into the table control only when `table` is missing from the
# `nlmixr2est::nlmixr()` call, so supplying an explicit default would silently
# switch that merge off. R propagates missingness through an argument pass, so
# `table` reaching here missing stays missing.
#
# Kept separate from nlmixr_fit_simple() so the `error = "stop"` and
# `error = "continue"` paths share one copy of that branching.
nlmixr_fit_simple_run <- function(ui, data, est, control, table) {
  if (missing(table)) {
    nlmixr2est::nlmixr(object = ui, data = data, est = est, control = control)
  } else {
    nlmixr2est::nlmixr(object = ui, data = data, est = est, control = control, table = table)
  }
}

# Build the failure sentinel returned by nlmixr_fit_simple() when
# `error = "continue"` and estimation throws. It mirrors the shape of a
# base::try() result -- a character vector holding the error message with the
# originating condition attached as the "condition" attribute -- but carries
# an `nlmixr2targetsError` class so downstream code can tell a failed fit
# apart from a real nlmixr2 fit with a simple inherits() check. The
# "try-error" class is kept so existing try-error-aware code recognizes it too.
nlmixr2targets_error_object <- function(cond) {
  structure(
    paste0("Error : ", conditionMessage(cond), "\n"),
    class = c("nlmixr2targetsError", "try-error"),
    condition = cond
  )
}

# Evaluate `expr`, returning its value on success. When `error == "continue"`,
# an error thrown while evaluating `expr` is caught and turned into the failure
# sentinel instead, so one failed model does not halt tar_make(); when
# `error == "stop"` the error propagates as usual. `expr` is an unforced
# promise, so it is evaluated only in the chosen branch -- callers put any
# upstream-sentinel passthrough check before the call, where `expr` is not yet
# touched. Shared by the object-, covariate- and data-simplification steps so
# the whole per-model chain honors error = "continue", matching the estimation
# step (nlmixr_fit_simple()).
nlmixr2targets_run_continue <- function(error, expr) {
  if (identical(error, "continue")) {
    tryCatch(expr, error = function(e) nlmixr2targets_error_object(e))
  } else {
    expr
  }
}

#' Print a failed `nlmixr2targets` estimation result
#'
#' When [tar_nlmixr()] or [tar_nlmixr_multimodel()] is called with
#' `error = "continue"` and the estimation step throws, the target stores a
#' lightweight failure sentinel of class `nlmixr2targetsError` instead of an
#' `nlmixr2` fit. This method prints the captured error message. Detect such a
#' sentinel with `inherits(x, "nlmixr2targetsError")` (or the broader
#' `inherits(x, "try-error")`).
#'
#' @param x A `nlmixr2targetsError` object.
#' @param ... Ignored; present for compatibility with [print()].
#' @returns `x`, invisibly.
#' @export
print.nlmixr2targetsError <- function(x, ...) {
  cat("<nlmixr2targets failed estimation>\n")
  cat(conditionMessage(attr(x, "condition")), "\n", sep = "")
  invisible(x)
}
